const files={"/":{"type":"text/html; charset=utf-8","data":""},"/assets/style.css":{"type":"text/css; charset=utf-8","data":""},"/assets/bootstrap.min.css":{"type":"text/css; charset=utf-8","data":""},"/assets/bootstrap.bundle.min.js":{"type":"text/javascript; charset=utf-8","data":""},"/site/agriya-theme.css":{"type":"text/css; charset=utf-8","data":""},"/site/agriya-logo.png":{"type":"image/png","data":""},"/site/agriya-loading.gif":{"type":"image/gif","data":""},"/site/app.js":{"type":"text/javascript; charset=utf-8","data":""},"/site/products.json":{"type":"application/json; charset=utf-8","data":""},"/site/leaf.svg":{"type":"image/svg+xml","data":""},"/site/field.jpg":{"type":"image/jpeg","data":""},"/site/product-range.png":{"type":"image/png","data":""}};
export default {fetch(request){const url=new URL(request.url);const path=url.pathname;const headers={'X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','X-Frame-Options':'DENY'};if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405,headers:{...headers,Allow:'GET, HEAD'}});if(path==='/robots.txt')return new Response('User-agent: *\nAllow: /',{headers:{...headers,'Content-Type':'text/plain'}});if(path==='/index.html'||path==='/theme2'||path.startsWith('/theme2/')||path.startsWith('/document/')||(/^\/[^/]+\.html$/.test(path)&&path!=='/index.html'))return new Response(null,{status:302,headers:{...headers,Location:'/'}});const file=files[path];if(!file)return new Response('Page not found. Visit Agriya Agro Tech at /.',{status:404,headers});const bytes=Uint8Array.from(atob(file.data),c=>c.charCodeAt(0));return new Response(request.method==='HEAD'?null:bytes,{headers:{...headers,'Content-Type':file.type,'Cache-Control':path==='/'?'no-cache':'public, max-age=3600'}});}};
